def generate_records() -> List[Dict[str, Any]]:
    categories = [
        (INPATIENT_SAMPLES, "Inpatient_Medical"),
        (OUTPATIENT_SAMPLES, "Outpatient_Emergency"),
        (CRITICAL_ILLNESS_SAMPLES, "Critical_Illness"),
        (ACCIDENT_SAMPLES, "Personal_Accident"),
        (INQUIRY_SAMPLES, "Inquiry_or_Dispute"),
    ]
    
    all_data = []
    
    for sample_list, cat_name in categories:
        for text, cat, urgency, primary_cond, claim_method, reasoning in sample_list:
            triage_obj = ClaimTriageOutput(
                category=cat,
                urgency=urgency,
                primary_condition=primary_cond,
                claim_method=claim_method,
                reasoning=reasoning
            )
            output_json_str = triage_obj.model_dump_json()
            
            # Formulate prompt format
            user_prompt = f"Lakukan triage dan analisis klaim asuransi untuk laporan nasabah berikut:\n\n{text}"
            
            record = {
                "instruction": SYSTEM_PROMPT,
                "input": text,
                "output": output_json_str,
                "category": cat.value,
                "urgency": urgency.value,
                "claim_method": claim_method.value,
                "messages": [
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": user_prompt},
                    {"role": "assistant", "content": output_json_str}
                ]
            }
            all_data.append(record)
            
    return all_data

def main():
    records = generate_records()
    total = len(records)
    print(f"Total curated seed records: {total}")
    
    # Stratified split: 80% train, 10% val, 10% test
    # First split off test (10% ~ 18 samples)
    train_val, test = train_test_split(
        records,
        test_size=18,
        stratify=[r["category"] for r in records],
        random_state=42
    )
    
    # Then split train and val (17 samples val, 140 samples train)
    train, val = train_test_split(
        train_val,
        test_size=17,
        stratify=[r["category"] for r in train_val],
        random_state=42
    )
    
    print(f"Train split count: {len(train)} (Target >= 120)")
    print(f"Val split count  : {len(val)} (Target >= 15)")
    print(f"Test split count : {len(test)} (Target >= 15)")
    
    os.makedirs("data", exist_ok=True)
    
    def write_jsonl(filename: str, dataset: List[Dict[str, Any]]):
        path = os.path.join("data", filename)
        with open(path, "w", encoding="utf-8") as f:
            for item in dataset:
                f.write(json.dumps(item, ensure_ascii=False) + "\n")
        print(f"Successfully saved {len(dataset)} records to {path}")
        
    write_jsonl("seed_train.jsonl", train)
    write_jsonl("seed_val.jsonl", val)
    write_jsonl("seed_test.jsonl", test)
    
    print("Seed dataset curation and split complete!")

if __name__ == "__main__":
    main()
